/**
 * Get a sample of queries for quick testing.
 */
export function getSampleQueries(n: number): GoldQuery[] {
    const categories = ["exact", "paraphrase", "thematic", "cross-chapter"];
    const perCategory = Math.ceil(n / categories.length);
    const result: GoldQuery[] = [];
    for (const cat of categories) {
        const catQueries = GOLD_QUERIES.filter(q => q.category === cat);
        result.push(...catQueries.slice(0, perCategory));
    }
    return result.slice(0, n);
}